import Link from 'next/link';

export default function HomePage() {
  return (
    <main>
      {/* ============ HERO ============ */}
      <section className="hero" aria-labelledby="hero-title">
        <div className="hero-bg" aria-hidden="true">
          <div className="hero-bg-gradient"></div>
          <div className="hero-bg-overlay"></div>
        </div>

        <div className="container">
          <div className="hero-text">
            <h1 id="hero-title" className="hero-title">
              <span data-i18n="hero.line1">Verified Experience. </span>
              <span data-i18n="hero.line2">Real Value.</span>
            </h1>

            <p className="hero-subtitle" data-i18n="hero.subtitle">
              We don't promise jobs. We give you verifiable proof to walk into any interview with confidence.
            </p>

            <div className="hero-cta">
              <Link className="btn-cta" href="/signup" data-i18n="hero.cta">
                Get Started for Free
              </Link>
              <p className="hero-note" data-i18n="hero.note">No credit card required</p>
            </div>
          </div>
        </div>
      </section>

      {/* ============ SECTION 1: DIGITAL EXPERIENCE CARD ============ */}
      <section className="feature" id="digital-card" aria-labelledby="feature-title">
        <div className="container">
          <div className="feature-grid">
            <div className="feature-copy">
              <p className="feature-tag" data-i18n="feature.tag">Digital Credentials</p>
              <h2 id="feature-title" className="feature-title" data-i18n="feature.title">
                One verifiable link. Infinite possibilities.
              </h2>
              <p className="feature-text" data-i18n="feature.text">
                Replace your traditional CV with a secure, tamper-proof digital card. Instantly prove your skills, experience, and licenses to employers with a single scan.
              </p>

              <ul className="check-list">
                <li>
                  <span className="check-icon" aria-hidden="true">
                    <svg viewBox="0 0 14 14"><path d="M2.5 7.5l3 3 6-7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                  </span>
                  <span data-i18n="feature.check1">Verified .edu.vn email</span>
                </li>
                <li>
                  <span className="check-icon" aria-hidden="true">
                    <svg viewBox="0 0 14 14"><path d="M2.5 7.5l3 3 6-7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                  </span>
                  <span data-i18n="feature.check2">Identity (CCCD) matched</span>
                </li>
                <li>
                  <span className="check-icon" aria-hidden="true">
                    <svg viewBox="0 0 14 14"><path d="M2.5 7.5l3 3 6-7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                  </span>
                  <span data-i18n="feature.check3">SHA-256 cryptographic signature</span>
                </li>
              </ul>
            </div>

            <div className="feature-visual">
              <article className="id-card" aria-label="Sample digital experience card" data-i18n-attr="aria-label:card.aria">
                <div className="id-card-top">
                  <p className="id-card-label" data-i18n="card.label">Verified Experience</p>
                  <span className="id-card-badge" data-i18n="card.badge">Verified</span>
                </div>

                <div className="id-card-bottom">
                  <div className="id-card-person">
                    <p className="id-card-name">Nguyen Van A</p>
                    <p className="id-card-role" data-i18n="card.role">Content Writer</p>
                  </div>
                  <div className="qr" role="img" aria-label="Sample QR code" data-i18n-attr="aria-label:card.qr">
                    <span className="qr-finder qr-finder-tl"></span>
                    <span className="qr-finder qr-finder-tr"></span>
                    <span className="qr-finder qr-finder-bl"></span>
                  </div>
                </div>
              </article>
            </div>
          </div>
        </div>
      </section>

      {/* ============ SECTION 2: STATISTICS BAR ============ */}
      <section className="stats" aria-label="VeriWork in numbers" data-i18n-attr="aria-label:stats.aria">
        <div className="container">
          <ul className="stats-list">
            <li className="stat">
              <span className="stat-number">128</span>
              <span className="stat-label" data-i18n="stats.cards">Digital Cards Issued</span>
            </li>
            <li className="stat">
              <span className="stat-number">96.8%</span>
              <span className="stat-label" data-i18n="stats.pass">First-Time Pass Rate</span>
            </li>
            <li className="stat">
              <span className="stat-number">0</span>
              <span className="stat-label" data-i18n="stats.disputes">Disputes</span>
            </li>
          </ul>
        </div>
      </section>

      {/* ============ SECTION 3: FINAL CALL-TO-ACTION ============ */}
      <section className="cta-final" aria-labelledby="cta-title">
        <div className="container">
          <div className="cta-final-grid">
            <div className="cta-final-copy">
              <h2 id="cta-title" className="cta-final-title" data-i18n="cta.title">
                Ready to build your verified future?
              </h2>
              <p className="cta-final-text" data-i18n="cta.text">
                Join thousands of students and professionals proving their real value. No credit card required.
              </p>
              <Link className="btn-cta" href="/signup" data-i18n="cta.button">
                Create Your Free Profile
              </Link>
            </div>

            <div className="cta-final-visual">
              <img 
                className="cta-final-img" 
                src="/cta-image.png" 
                alt="Student showing their verified VeriWork profile" 
                data-i18n-attr="alt:cta.imgAlt" 
                width="800" 
                height="600" 
                loading="lazy" 
                decoding="async" 
              />
            </div>
          </div>
        </div>
      </section>
    </main>
  );
}   